    13→module query_test {
    14→    // === 테스트 유틸리티 ===
    15→
    16→    struct TestResult {
    17→        name:    string;
    18→        passed:  bool;
    19→        message: string;
    20→    }
    21→
    22→    func assert_true(condition: bool, name: string) -> TestResult {
    23→        return TestResult{
    24→            name:    name,
    25→            passed:  condition,
    26→            message: if condition { "PASS" } else { "FAIL" },
    27→        };
    28→    }
    29→
    30→    func assert_eq_i32(actual: i32, expected: i32, name: string) -> TestResult {
    31→        let passed = actual == expected;
    32→        return TestResult{
    33→            name:    name,
    34→            passed:  passed,
    35→            message: if passed { "PASS" } else { "FAIL: expected " + i32_to_str(expected) + " got " + i32_to_str(actual) },
    36→        };
    37→    }
    38→
    39→    func assert_eq_i64(actual: i64, expected: i64, name: string) -> TestResult {
    40→        let passed = actual == expected;
    41→        return TestResult{
    42→            name:    name,
    43→            passed:  passed,
    44→            message: if passed { "PASS" } else { "FAIL: expected " + i64_to_str(expected) + " got " + i64_to_str(actual) },
    45→        };
    46→    }
    47→
    48→    func assert_eq_str(actual: string, expected: string, name: string) -> TestResult {
    49→        let passed = actual == expected;
    50→        return TestResult{
    51→            name:    name,
    52→            passed:  passed,
    53→            message: if passed { "PASS" } else { "FAIL: expected \"" + expected + "\" got \"" + actual + "\"" },
    54→        };
    55→    }
    56→
    57→    func print_result(r: TestResult) {
    58→        let status = if r.passed { "[PASS]" } else { "[FAIL]" };
    59→        print(status + " " + r.name + " - " + r.message);
    60→    }
    61→
    62→    // === 공통 스키마: users 테이블 ===
    63→    // 컬럼: id(INT), name(STR), age(INT), active(BOOL)
    64→    // INT 컬럼 순서: id=int_vals[0], age=int_vals[1]
    65→    // STR 컬럼 순서: name=str_vals[0]
    66→    // BOOL 컬럼 순서: active=bool_vals[0]
    67→
    68→    func make_users_schema() -> schema.TableSchema {
    69→        let s = schema.schema_new("users");
    70→        s.schema_add_col("id",     schema.COL_TYPE_INT,  false);
    71→        s.schema_add_col("name",   schema.COL_TYPE_STR,  false);
    72→        s.schema_add_col("age",    schema.COL_TYPE_INT,  true);
    73→        s.schema_add_col("active", schema.COL_TYPE_BOOL, false);
    74→        return s;
    75→    }
    76→
    77→    func make_user_row(id: i64, name: string, age: i64, active: bool) -> schema.RecordRow {
    78→        let row = schema.record_new();
    79→        row.int_vals[0] = id;
    80→        row.int_vals[1] = age;
    81→        row.str_vals[0] = name;
    82→        row.bool_vals[0] = active;
    83→        return row;
    84→    }
    85→
    86→    // === 테스트 1: 스키마 + 테이블 기본 CRUD ===
    87→
    88→    func test_schema_crud() {
    89→        print("\n=== Test 1: Schema & Table CRUD ===");
    90→
    91→        let s = make_users_schema();
    92→
    93→        // 스키마 검증
    94→        let r1 = assert_eq_i32(s.col_count, 4, "schema col_count == 4");
    95→        print_result(r1);
    96→
    97→        let col_idx, found = s.schema_find_col("age");
    98→        let r2 = assert_true(found && col_idx == 2, "schema_find_col 'age' == 2");
    99→        print_result(r2);
